@section('content')<section class="container page-space">@include('nav')<h1>Consultas por WhatsApp</h1><p>La confirmación se registra manualmente.</p>@forelse($items as $item)<article class="dashboard-item"><div><h2>{{ $item->title }}</h2><p>{{ $item->createdAt }} · {{ $item->status }}</p></div><form method="post" action="{{ url(request()->path().'/'.$item->id).'?'.http_build_query(request()->only('datos')) }}">@csrf<select aria-label="Estado" name="status">@foreach(['INITIATED'=>'Sin seguimiento','RESPONDED'=>'Respondida','CONFIRMED'=>'Estadía reportada','LOST'=>'No concretada'] as $key=>$label)<option value="{{ $key }}" @selected($item->status===$key)>{{ $label }}</option>@endforeach</select><label>Motivo de pérdida<select name="lossReason"><option value="">Elegir</option>@foreach(['Precio','Sin disponibilidad','No respondió','No se ajusta a lo buscado','Otro'] as $reason)<option>{{ $reason }}</option>@endforeach</select></label><label>Nota<input name="note" maxlength="500"></label><button>Guardar seguimiento</button></form></article>@empty<p>Aún no hay contactos.</p>@endforelse @include('pagination')</section>@endsection
